create or replace function edoc.edoc_internal_dispatch_scope_v1(p_actor_user_id text,p_dispatch_id text)
returns boolean language sql stable security invoker set search_path='' as $$
  select exists(
    select 1 from edoc.internal_dispatches d
    join edoc.users a on a.id=p_actor_user_id and a.status='啟用'
    left join edoc.inbound_documents i on i.id=d.inbound_document_id
    left join edoc.official_documents o on o.id=d.official_document_id and i.id is null
    left join edoc.companies c on c.id=o.company_id
    left join edoc.users s on s.id=d.sender_user_id and i.id is null and o.id is null
    where d.id=p_dispatch_id and nullif(a.company_id,'') is not null and nullif(a.finance_tenant_id,'') is not null
      and coalesce(i.company_id,o.company_id,s.company_id)=a.company_id
      and coalesce(i.finance_tenant_id,c.finance_tenant_id,s.finance_tenant_id)=a.finance_tenant_id
  )
$$;

create or replace function edoc.edoc_dispatch_log_v1(p_actor text,p_dispatch text,p_action text,p_detail text)
returns void language plpgsql security invoker set search_path='' as $$
declare v_id text := pg_catalog.md5(pg_catalog.random()::text||pg_catalog.clock_timestamp()::text); v_actor edoc.users%rowtype;
begin
  select * into strict v_actor from edoc.users where id=p_actor;
  insert into edoc.internal_dispatch_logs(id,dispatch_id,actor_id,action,detail,created_at)
    values('IDLOG-'||v_id,p_dispatch,p_actor,p_action,p_detail,pg_catalog.to_char(pg_catalog.clock_timestamp(),'YYYY-MM-DD HH24:MI:SS'));
  insert into edoc.audit_logs(id,actor,action,target_type,target_id,detail,event_type,module_code,result,severity,created_at)
    values('AUD-IDISP-'||v_id,v_actor.name,p_action,'internal_dispatches',p_dispatch,p_detail,'submit','official_documents','success','info',pg_catalog.to_char(pg_catalog.clock_timestamp(),'YYYY-MM-DD HH24:MI:SS'));
end $$;

create or replace function edoc.edoc_list_internal_dispatches_v1(
  p_actor_user_id text,p_company_wide boolean,p_needs_reply boolean,p_status text,p_limit integer,p_after_created text,p_after_id text
) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare v_actor edoc.users%rowtype; v_result jsonb;
begin
  select * into v_actor from edoc.users where id=p_actor_user_id and status='啟用';
  if not found or nullif(v_actor.company_id,'') is null or nullif(v_actor.finance_tenant_id,'') is null then
    raise exception using errcode='42501',message='internal_dispatch_company_forbidden';
  end if;
  if p_limit not between 1 and 101 or (p_after_created is null)<>(p_after_id is null) then
    raise exception using errcode='22023',message='internal_dispatch_list_filter_invalid';
  end if;
  with candidates as materialized (
    select d.* from edoc.internal_dispatches d
    left join edoc.inbound_documents i on i.id=d.inbound_document_id
    left join edoc.official_documents o on o.id=d.official_document_id and i.id is null
    left join edoc.companies c on c.id=o.company_id
    left join edoc.users s on s.id=d.sender_user_id and i.id is null and o.id is null
    where coalesce(i.company_id,o.company_id,s.company_id)=v_actor.company_id
      and coalesce(i.finance_tenant_id,c.finance_tenant_id,s.finance_tenant_id)=v_actor.finance_tenant_id
      and (p_company_wide or d.sender_user_id=p_actor_user_id or exists(select 1 from edoc.internal_dispatch_recipients r where r.dispatch_id=d.id and r.recipient_user_id=p_actor_user_id))
      and (not p_needs_reply or d.status not in ('closed','cancelled') and nullif(d.closed_at,'') is null and exists(select 1 from edoc.internal_dispatch_recipients r where r.dispatch_id=d.id and r.recipient_user_id=p_actor_user_id and r.action_required and r.status not in ('replied','reassigned')))
      and (nullif(p_status,'') is null or d.status=p_status)
      and (p_after_created is null or (d.created_at,d.id)<(p_after_created,p_after_id))
    order by d.created_at desc,d.id desc limit p_limit
  )
  select pg_catalog.jsonb_build_object('items',coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d)||pg_catalog.jsonb_build_object(
    'metadata',d.metadata_json,
    'recipients',coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by r.created_at,r.id) from edoc.internal_dispatch_recipients r where r.dispatch_id=d.id),'[]'::jsonb),
    'pending_reply_count',(select count(*) from edoc.internal_dispatch_recipients r where r.dispatch_id=d.id and r.action_required and r.status not in ('replied','reassigned')),
    'replies',coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)||pg_catalog.jsonb_build_object('attachment',case when f.id is null then null else pg_catalog.jsonb_build_object('attachment_file_id',f.id,'file_name',f.file_name,'mime_type',f.mime_type,'file_size',f.size_bytes,'sha256',f.sha256,'scan_status',f.scan_status) end) order by r.created_at desc,r.id desc)
      from edoc.internal_dispatch_replies r left join edoc.file_objects f on f.id=r.attachment_file_id where r.dispatch_id=d.id),'[]'::jsonb),
    'logs',coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(l) order by l.created_at desc,l.id desc) from edoc.internal_dispatch_logs l where l.dispatch_id=d.id),'[]'::jsonb),
    'inbound_document',(select pg_catalog.to_jsonb(i)||pg_catalog.jsonb_build_object(
      'metadata',coalesce(nullif(i.metadata_json,'')::jsonb,'{}'::jsonb),
      'attachments',coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(a) order by a.created_at desc,a.id desc) from edoc.inbound_document_attachments a where a.inbound_document_id=i.id),'[]'::jsonb),
      'handover_required',nullif(i.assignee_user_id,'') is not null and i.status not in ('closed','archived','cancelled') and not exists(
        select 1 from edoc.users u where u.id=i.assignee_user_id and u.status='啟用' and u.company_id=i.company_id and u.finance_tenant_id=i.finance_tenant_id)
    ) from edoc.inbound_documents i where i.id=d.inbound_document_id)
  ) order by d.created_at desc,d.id desc),'[]'::jsonb)) into v_result from candidates d;
  return v_result;
end $$;

create or replace function edoc.edoc_create_internal_dispatch_v1(p_actor_user_id text,p_plan jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare
  v_actor edoc.users%rowtype; v_recipient edoc.users%rowtype; v_existing edoc.internal_dispatch_mutations%rowtype;
  v_row jsonb := p_plan->'dispatch'; v_rec jsonb; v_key text:=p_plan->>'key'; v_hash text:=p_plan->>'hash';
  v_id text:=p_plan#>>'{dispatch,id}'; v_now text:=pg_catalog.to_char(pg_catalog.clock_timestamp(),'YYYY-MM-DD HH24:MI:SS');
  v_required boolean; v_scope_company text; v_scope_tenant text;
begin
  select * into v_actor from edoc.users where id=p_actor_user_id and status='啟用' for share;
  if not found or nullif(v_actor.company_id,'') is null or nullif(v_actor.finance_tenant_id,'') is null then
    raise exception using errcode='42501',message='internal_dispatch_company_forbidden';
  end if;
  if v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$' or v_hash !~ '^[0-9a-f]{64}$' or nullif(v_id,'') is null then
    raise exception using errcode='22023',message='internal_dispatch_request_invalid';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('dispatch-create:'||p_actor_user_id||':'||v_key,0));
  select * into v_existing from edoc.internal_dispatch_mutations where actor_user_id=p_actor_user_id and idempotency_key=v_key;
  if found then
    if v_existing.request_sha256<>v_hash then raise exception using errcode='PT409',message='internal_dispatch_idempotency_conflict'; end if;
    if not edoc.edoc_internal_dispatch_scope_v1(p_actor_user_id,v_existing.dispatch_id) then raise exception using errcode='42501',message='internal_dispatch_company_forbidden'; end if;
    return pg_catalog.jsonb_build_object('id',v_existing.dispatch_id,'replayed',true);
  end if;
  -- HTTP authorization is server-owned. Repeat stored role authority here.
  if v_actor.role not in ('總務','行政部主任','行政部門主任','執行長') then
    raise exception using errcode='42501',message='internal_dispatch_create_forbidden';
  end if;
  if nullif(v_row->>'inbound_document_id','') is not null then
    select company_id,finance_tenant_id into v_scope_company,v_scope_tenant from edoc.inbound_documents where id=v_row->>'inbound_document_id' for share;
    if not found or v_scope_company is distinct from v_actor.company_id or v_scope_tenant is distinct from v_actor.finance_tenant_id then
      raise exception using errcode='42501',message='internal_dispatch_company_forbidden';
    end if;
  end if;
  if nullif(v_row->>'official_document_id','') is not null then
    select d.company_id,c.finance_tenant_id into v_scope_company,v_scope_tenant from edoc.official_documents d join edoc.companies c on c.id=d.company_id where d.id=v_row->>'official_document_id';
    if not found or v_scope_company is distinct from v_actor.company_id or v_scope_tenant is distinct from v_actor.finance_tenant_id then
      raise exception using errcode='42501',message='internal_dispatch_company_forbidden';
    end if;
  end if;
  if pg_catalog.jsonb_typeof(p_plan->'recipients')<>'array' or pg_catalog.jsonb_array_length(p_plan->'recipients')=0 then
    raise exception using errcode='22023',message='internal_dispatch_recipients_required';
  end if;
  select exists(select 1 from pg_catalog.jsonb_array_elements(p_plan->'recipients') r where (r->>'action_required')::boolean) into v_required;
  insert into edoc.internal_dispatches(id,official_document_id,inbound_document_id,title,subject,body,sender_user_id,sender_name,sender_department,reply_required,reply_due_days,due_at,reply_status,status,metadata_json,created_at,updated_at,closed_at)
    values(v_id,nullif(v_row->>'official_document_id',''),nullif(v_row->>'inbound_document_id',''),v_row->>'title',v_row->>'subject',v_row->>'body',v_actor.id,v_actor.name,v_actor.unit,v_required,(v_row->>'reply_due_days')::integer,v_row->>'due_at',case when v_required then 'pending' else 'not_required' end,'sent',coalesce(v_row->'metadata_json','{}'::jsonb),v_now,v_now,'');
  for v_rec in select value from pg_catalog.jsonb_array_elements(p_plan->'recipients') loop
    if nullif(v_rec->>'recipient_user_id','') is not null then
      select * into v_recipient from edoc.users where id=v_rec->>'recipient_user_id' and status='啟用' for share;
      if not found then raise exception using errcode='22023',message='internal_dispatch_recipient_not_found'; end if;
      if v_recipient.company_id is distinct from v_actor.company_id or v_recipient.finance_tenant_id is distinct from v_actor.finance_tenant_id then
        raise exception using errcode='42501',message='internal_dispatch_recipient_company_forbidden';
      end if;
    elsif not exists(select 1 from edoc.department_registry d join edoc.companies c on c.name=d.company_name
                     where d.id=v_rec->>'recipient_department_id' and d.status='啟用' and c.id=v_actor.company_id and c.finance_tenant_id=v_actor.finance_tenant_id) then
      raise exception using errcode='42501',message='internal_dispatch_recipient_company_forbidden';
    end if;
    if exists(select 1 from edoc.internal_dispatch_recipients where dispatch_id=v_id and
      (nullif(v_rec->>'recipient_user_id','') is not null and recipient_user_id=v_rec->>'recipient_user_id'
       or nullif(v_rec->>'recipient_user_id','') is null and recipient_type='department' and recipient_department_id=v_rec->>'recipient_department_id')) then
      raise exception using errcode='22023',message='internal_dispatch_duplicate_recipient';
    end if;
    insert into edoc.internal_dispatch_recipients(id,dispatch_id,recipient_type,recipient_user_id,recipient_department_id,recipient_name,action_required,status,read_at,replied_at,created_at,updated_at)
      values(v_rec->>'id',v_id,case when nullif(v_rec->>'recipient_user_id','') is null then 'department' else 'user' end,v_rec->>'recipient_user_id',v_rec->>'recipient_department_id',case when nullif(v_rec->>'recipient_user_id','') is null then v_rec->>'recipient_name' else v_recipient.name end,(v_rec->>'action_required')::boolean,case when (v_rec->>'action_required')::boolean then 'pending' else 'informed' end,'','',v_now,v_now);
    if nullif(v_rec->>'recipient_user_id','') is not null then
      insert into edoc.notifications(id,type,title,target_role,target_user_id,target_company_id,target_email,channel,status,priority,source,action_url,body,created_at)
        values('NTF-DISPATCH-'||pg_catalog.md5(v_id||':'||v_recipient.id),'內部派文',v_row->>'subject',v_recipient.role,v_recipient.id,v_recipient.company_id,v_recipient.email,'Email + 系統通知','未讀','中',v_id,'/#inbound',
          v_actor.name||' 發送內部公文。'||case when (v_rec->>'action_required')::boolean then '請於 '||coalesce(v_row->>'due_at','期限')||' 前處理並回覆。' else '此件僅供知悉，不需回覆。' end,pg_catalog.clock_timestamp());
    end if;
  end loop;
  perform edoc.edoc_dispatch_log_v1(v_actor.id,v_id,'create_internal_dispatch',v_row->>'subject');
  insert into edoc.internal_dispatch_mutations values(v_actor.id,v_key,v_hash,v_id,v_now);
  return pg_catalog.jsonb_build_object('id',v_id,'replayed',false);
end $$;

create or replace function edoc.edoc_close_internal_dispatch_v1(p_actor_user_id text,p_dispatch_id text,p_company_wide boolean,p_comment text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_row edoc.internal_dispatches%rowtype;
begin
  select * into v_row from edoc.internal_dispatches where id=p_dispatch_id for update;
  if not found then raise exception using errcode='22023',message='internal_dispatch_not_found'; end if;
  if not edoc.edoc_internal_dispatch_scope_v1(p_actor_user_id,p_dispatch_id) then raise exception using errcode='42501',message='internal_dispatch_company_forbidden'; end if;
  if v_row.sender_user_id<>p_actor_user_id and not p_company_wide then raise exception using errcode='42501',message='internal_dispatch_close_forbidden'; end if;
  if v_row.status='closed' then return pg_catalog.jsonb_build_object('id',p_dispatch_id,'replayed',true); end if;
  if v_row.status='cancelled' then raise exception using errcode='PT409',message='internal_dispatch_closed'; end if;
  if exists(select 1 from edoc.internal_dispatch_recipients where dispatch_id=p_dispatch_id and action_required and status not in ('replied','reassigned')) then
    raise exception using errcode='PT409',message='internal_dispatch_pending_replies';
  end if;
  update edoc.internal_dispatches set status='closed',closed_at=pg_catalog.to_char(pg_catalog.clock_timestamp(),'YYYY-MM-DD HH24:MI:SS'),updated_at=pg_catalog.to_char(pg_catalog.clock_timestamp(),'YYYY-MM-DD HH24:MI:SS') where id=p_dispatch_id;
  perform edoc.edoc_dispatch_log_v1(p_actor_user_id,p_dispatch_id,'close_internal_dispatch',p_comment);
  return pg_catalog.jsonb_build_object('id',p_dispatch_id,'replayed',false);
end $$;

create or replace function edoc.edoc_reply_internal_dispatch_v1(p_actor_user_id text,p_dispatch_id text,p_reply jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_row edoc.internal_dispatches%rowtype; v_rec edoc.internal_dispatch_recipients%rowtype; v_actor edoc.users%rowtype; v_now text:=pg_catalog.to_char(pg_catalog.clock_timestamp(),'YYYY-MM-DD HH24:MI:SS');
begin
  -- Same lock as close and reassignment: no stale checks followed by a write.
  select * into v_row from edoc.internal_dispatches where id=p_dispatch_id for update;
  if not found then raise exception using errcode='22023',message='internal_dispatch_not_found'; end if;
  if not edoc.edoc_internal_dispatch_scope_v1(p_actor_user_id,p_dispatch_id) then raise exception using errcode='42501',message='internal_dispatch_company_forbidden'; end if;
  select * into v_actor from edoc.users where id=p_actor_user_id and status='啟用';
  select * into v_rec from edoc.internal_dispatch_recipients where dispatch_id=p_dispatch_id and recipient_user_id=p_actor_user_id and status<>'reassigned' order by (action_required and status<>'replied') desc,created_at desc,id desc limit 1 for update;
  if not found then raise exception using errcode='42501',message='internal_dispatch_reply_forbidden'; end if;
  if not v_rec.action_required then raise exception using errcode='42501',message='internal_dispatch_reply_not_required'; end if;
  if v_row.status in ('closed','cancelled') or nullif(v_row.closed_at,'') is not null then raise exception using errcode='PT409',message='internal_dispatch_closed'; end if;
  insert into edoc.internal_dispatch_replies(id,dispatch_id,recipient_id,replier_user_id,replier_name,reply_text,attachment_file_id,status,created_at)
    values(p_reply->>'id',p_dispatch_id,v_rec.id,v_actor.id,v_actor.name,p_reply->>'reply_text',nullif(p_reply->>'attachment_file_id',''),'submitted',v_now);
  update edoc.internal_dispatch_recipients set status='replied',replied_at=v_now,updated_at=v_now where id=v_rec.id;
  if not exists(select 1 from edoc.internal_dispatch_recipients where dispatch_id=p_dispatch_id and action_required and status not in ('replied','reassigned')) then
    update edoc.internal_dispatches set reply_status='completed',status='reply_completed',updated_at=v_now where id=p_dispatch_id;
  end if;
  perform edoc.edoc_dispatch_log_v1(p_actor_user_id,p_dispatch_id,'reply_internal_dispatch',p_reply->>'reply_text');
  return pg_catalog.jsonb_build_object('id',p_dispatch_id);
end $$;

create or replace function edoc.edoc_assign_inbound_with_dispatch_v1(p_mutation_type text,p_idempotency_key text,p_request_sha256 text,p_actor_user_id text,p_document_id text,p_expected_version bigint,p_payload jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare
  v_old text; v_response jsonb; v_assignee edoc.users%rowtype; v_rec record; v_new text; v_now text:=pg_catalog.to_char(pg_catalog.clock_timestamp(),'YYYY-MM-DD HH24:MI:SS'); v_detail text;
begin
  if p_mutation_type<>'assign' then raise exception using errcode='22023',message='inbound_mutation_type_invalid'; end if;
  -- Match core RPC order: request lock, inbound lock, dispatch IDs in order.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key,0));
  select assignee_user_id into v_old from edoc.inbound_documents where id=p_document_id for update;
  v_response:=edoc.edoc_mutate_inbound_document_v1(p_mutation_type,p_idempotency_key,p_request_sha256,p_actor_user_id,p_document_id,p_expected_version,p_payload);
  if coalesce((v_response->>'replayed')::boolean,false) then return v_response; end if;
  select * into strict v_assignee from edoc.users where id=v_response#>>'{item,assignee_user_id}';
  if nullif(v_old,'') is null or v_old=v_assignee.id then return v_response; end if;
  -- Lock ALL affected dispatches before examining recipient obligations.
  perform id from edoc.internal_dispatches where inbound_document_id=p_document_id order by id for update;
  for v_rec in select r.* from edoc.internal_dispatch_recipients r join edoc.internal_dispatches d on d.id=r.dispatch_id
    where d.inbound_document_id=p_document_id and d.status not in ('closed','cancelled') and nullif(d.closed_at,'') is null
      and r.recipient_user_id=v_old and r.action_required and r.status not in ('replied','reassigned') order by d.id,r.id
  loop
    select id into v_new from edoc.internal_dispatch_recipients where dispatch_id=v_rec.dispatch_id and recipient_user_id=v_assignee.id and status not in ('replied','reassigned') order by id limit 1;
    if found then
      update edoc.internal_dispatch_recipients set action_required=true,status='pending',updated_at=v_now where id=v_new;
    else
      v_new:='IDREC-'||pg_catalog.md5(v_rec.id||':'||v_assignee.id||':'||p_idempotency_key);
      insert into edoc.internal_dispatch_recipients(id,dispatch_id,recipient_type,recipient_user_id,recipient_department_id,recipient_name,action_required,status,created_at,updated_at)
        values(v_new,v_rec.dispatch_id,'user',v_assignee.id,v_assignee.unit,v_assignee.name,true,'pending',v_now,v_now);
    end if;
    update edoc.internal_dispatch_recipients set action_required=false,status='reassigned',updated_at=v_now where id=v_rec.id;
    update edoc.internal_dispatches set reply_required=true,reply_status='pending',status='sent',updated_at=v_now where id=v_rec.dispatch_id;
    v_detail:=pg_catalog.jsonb_build_object('inbound_document_id',p_document_id,'previous_recipient_id',v_rec.id,'previous_user_id',v_old,'recipient_id',v_new,'recipient_user_id',v_assignee.id)::text;
    perform edoc.edoc_dispatch_log_v1(p_actor_user_id,v_rec.dispatch_id,'reassign_internal_dispatch',v_detail);
    insert into edoc.notifications(id,type,title,target_role,target_user_id,target_company_id,target_email,channel,status,priority,source,action_url,body,created_at)
      values('NTF-HANDOFF-'||pg_catalog.md5(v_rec.id||':'||v_new),'內部派文交接','未結派文已移交給你',v_assignee.role,v_assignee.id,v_assignee.company_id,v_assignee.email,'Email + 系統通知','未讀','中',v_rec.dispatch_id,'/#inbound','請查看原案與期限並完成待回覆事項。',pg_catalog.clock_timestamp());
  end loop;
  return v_response;
end $$;

